11	export class PanelSystem extends createSystem({
12	  welcomePanel: {
13	    required: [PanelUI, PanelDocument],
14	    where: [eq(PanelUI, "config", "./ui/welcome.json")],
15	  },
16	}) {
17	  init() {
18	    this.queries.welcomePanel.subscribe("qualify", (entity) => {
19	      const document = PanelDocument.data.document[
20	        entity.index
21	      ] as UIKitDocument;
22	      if (!document) {
23	        return;
24	      }
25	
26	      const xrButton = document.getElementById("xr-button") as UIKit.Text;
27	      xrButton.addEventListener("click", () => {
28	        if (this.world.visibilityState.value === VisibilityState.NonImmersive) {
29	          this.world.launchXR();
30	        } else {
31	          this.world.exitXR();
32	        }
33	      });
34	      this.world.visibilityState.subscribe((visibilityState) => {
35	        if (visibilityState === VisibilityState.NonImmersive) {
36	          xrButton.setProperties({ text: "Enter XR" });
37	        } else {
38	          xrButton.setProperties({ text: "Exit to Browser" });
39	        }
40	      });
41	    });
42	  }
43	}
