11	export class RobotSystem extends createSystem({
12	  robot: { required: [Robot] },
13	  robotClicked: { required: [Robot, Pressed] },
14	}) {
15	  private lookAtTarget!: Vector3;
16	  private vec3!: Vector3;
17	
18	  init() {
19	    this.lookAtTarget = new Vector3();
20	    this.vec3 = new Vector3();
21	    this.queries.robotClicked.subscribe("qualify", (entity) => {
22	      AudioUtils.play(entity);
23	    });
24	  }
25	
26	  update() {
27	    this.queries.robot.entities.forEach((entity) => {
28	      this.player.head.getWorldPosition(this.lookAtTarget);
29	      const spinnerObject = entity.object3D!;
30	      spinnerObject.getWorldPosition(this.vec3);
31	      this.lookAtTarget.y = this.vec3.y;
32	      spinnerObject.lookAt(this.lookAtTarget);
33	    });
34	  }
35	}
